 'use server'

import { createClient } from '@/utils/supabase/server'
import { redirect } from 'next/navigation'

export async function purchaseTickets(
  eventId: string,
  email: string,
  quantity: number
) {
  const supabase = await createClient()

  const safeQuantity = Number.isFinite(quantity) && quantity > 0 ? quantity : 1

  const rows = Array.from({ length: safeQuantity }, () => ({
    event_id: eventId,
    customer_email: email,
    status: 'paid' as const,
    // qr_token: will be generated by Postgres default if configured
  }))

  const { data: insertedTickets, error } = await supabase
    .from('tickets')
    .insert(rows)
    .select('id') // Pedimos que nos devuelva los IDs

  if (error) {
    console.error('Error inserting tickets', error)
    throw new Error('No se pudo completar la compra. Inténtalo de nuevo.')
  }

  const ticketIds =
    insertedTickets?.map((t: { id: string | number }) => t.id).join(',') ?? ''

  redirect(`/success?ids=${ticketIds}&email=${encodeURIComponent(email)}`)
}

type ValidateTicketResult =
  | {
      success: false
      message: string
    }
  | {
      success: true
      message: string
      data: {
        eventTitle: string | null
        email: string | null
      }
    }

export async function validateTicket(qrToken: string): Promise<ValidateTicketResult> {
  const supabase = await createClient()

  const { data: ticket, error } = await supabase
    .from('tickets')
    .select(
      'id, status, validated_at, customer_email, event:events(title)'
    )
    .eq('qr_token', qrToken)
    .maybeSingle()

  if (error) {
    console.error('Error fetching ticket for validation', error)
    return {
      success: false,
      message: 'Error al validar el ticket. Intenta de nuevo.',
    }
  }

  // Caso 1: No existe
  if (!ticket) {
    return {
      success: false,
      message: 'Ticket NO VÁLIDO ❌',
    }
  }

  const { id, status, validated_at, customer_email, event } = ticket as {
    id: string
    status: 'paid' | 'used' | string
    validated_at: string | null
    customer_email: string | null
    event: { title: string | null } | null
  }

  // Caso 2: Ya usado
  if (status === 'used') {
    const when = validated_at
      ? new Date(validated_at).toLocaleString('es-ES')
      : 'antes'

    return {
      success: false,
      message: `Ticket YA USADO (Hora: ${when}) ⚠️`,
    }
  }

  // Caso 3: Éxito -> marcar como usado
  if (status === 'paid') {
    const nowIso = new Date().toISOString()

    const { error: updateError } = await supabase
      .from('tickets')
      .update({ status: 'used', validated_at: nowIso })
      .eq('id', id)

    if (updateError) {
      console.error('Error updating ticket as used', updateError)
      return {
        success: false,
        message: 'No se pudo marcar el ticket como usado. Intenta de nuevo.',
      }
    }

    return {
      success: true,
      message: 'ACCESO PERMITIDO ✅',
      data: {
        eventTitle: event?.title ?? null,
        email: customer_email ?? null,
      },
    }
  }

  // Estado desconocido / no permitido
  return {
    success: false,
    message: 'Estado de ticket no válido para acceso.',
  }
}


